INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20A8XT1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A machine labels $23$ bottles every $4$ minutes. At this constant rate, how many bottles does the machine label in $52$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$276$"},{"key":"B","text":"$299$"},{"key":"C","text":"$92$"},{"key":"D","text":"$1{,}196$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{23 \\text{ bottles}}{4 \\text{ minutes}}$. In $52$ minutes there are $\\frac{52}{4} = 13$ intervals, so the machine labels $23 \\times 13 = 299$ bottles. The value $276$ results from an arithmetic slip such as computing $23 \\times 12 = 276$ instead of $23 \\times 13$. The value $92$ comes from multiplying $4 \\times 23 = 92$, confusing the interval length with the number of intervals. The value $1{,}196$ results from multiplying $23 \\times 52 = 1{,}196$ without dividing by $4$, treating the rate as $23$ bottles per minute.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20VP33M', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'From point $A$ on level ground, the angle of elevation to the top of a building is $33°$. From point $B$, which is $41$ meters closer to the building along the same straight line, the angle of elevation to the top of the building is $49°$. What is the height of the building, to the nearest meter?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '61', ARRAY['61'], E'Let $h$ be the height of the building and $d$ be the horizontal distance from point $B$ to the base of the building. From point $B$: $\\tan(49°) = \\frac{h}{d}$, so $h = d \\cdot \\tan(49°)$. From point $A$: $\\tan(33°) = \\frac{h}{d + 41}$, so $h = (d + 41) \\cdot \\tan(33°)$. Setting the two expressions equal: $d \\cdot \\tan(49°) = (d + 41) \\cdot \\tan(33°)$. Using $\\tan(49°) \\approx 1.1504$ and $\\tan(33°) \\approx 0.6494$: $1.1504d = 0.6494d + 0.6494 \\times 41$. Solving: $0.5010d = 26.63$, so $d \\approx 53.15$. Therefore $h = 53.15 \\times 1.1504 \\approx 61.1$, which rounds to $61$ meters. Common errors include using sine or cosine instead of tangent, or setting up only one equation and having insufficient information.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM215AO9B', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'grid_in', E'In the equation $4x + 9y = 83$, if $y = 7$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Substituting $y = 7$ gives $4x + 9(7) = 83$, which simplifies to $4x + 63 = 83$. Subtracting $63$ from both sides yields $4x = 20$, and dividing by $4$ gives $x = 5$. A common error is a sign mistake when subtracting, such as computing $83 + 63 = 146$ and dividing by $4$ to get $36.5$. Another error is dividing $83$ by $4$ directly without subtracting $63$ first.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22BFQGZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $(3x + 11)°$, the measure of angle $Q$ is $(5x - 7)°$, and the measure of angle $R$ is $(2x + 6)°$. What is the measure, in degrees, of the largest angle of the triangle?', NULL, $lyceon_json$[{"key":"A","text":"$17$"},{"key":"B","text":"$62$"},{"key":"C","text":"$78$"},{"key":"D","text":"$83$"}]$lyceon_json$::jsonb, 'C', NULL, E'Setting the angle sum equal to $180°$: $(3x + 11) + (5x - 7) + (2x + 6) = 180$, which simplifies to $10x + 10 = 180$, giving $x = 17$. The three angles are $3(17) + 11 = 62°$, $5(17) - 7 = 78°$, and $2(17) + 6 = 40°$. The largest angle is $78°$. The value $17$ comes from stopping at the value of $x$ without substituting back. The value $62°$ is angle $P$, not the largest. The value $83°$ results from omitting the constant $+10$ when solving $10x + 10 = 180$, incorrectly getting $x = 18$ and then $5(18) - 7 = 83$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM230XI5H', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'If $x^2 - 11x - 42 = 0$ and $x > 0$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '14', ARRAY['14'], E'Factor the quadratic: $x^2 - 11x - 42 = (x - 14)(x + 3) = 0$, since $(-14)(3) = -42$ and $-14 + 3 = -11$. Setting each factor to zero gives $x = 14$ or $x = -3$. Since the problem requires $x > 0$, the answer is $14$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23HHZ3Y', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'What are the solutions to the equation $\\sqrt{8x + 33} = x + 3$?', NULL, $lyceon_json$[{"key":"A","text":"$-4$ only"},{"key":"B","text":"$6$ only"},{"key":"C","text":"$-4$ and $6$"},{"key":"D","text":"$-6$ only"}]$lyceon_json$::jsonb, 'B', NULL, E'Squaring both sides gives $8x + 33 = (x + 3)^2 = x^2 + 6x + 9$. Rearranging: $x^2 - 2x - 24 = 0$, which factors as $(x - 6)(x + 4) = 0$, yielding $x = 6$ or $x = -4$. Both must be checked in the original equation. For $x = -4$: $\\sqrt{8(-4) + 33} = \\sqrt{1} = 1$ but $-4 + 3 = -1$, so $1 \\neq -1$ and $x = -4$ is extraneous. For $x = 6$: $\\sqrt{8(6) + 33} = \\sqrt{81} = 9$ and $6 + 3 = 9$, which checks. The only valid solution is $6$. The distractor stating $-4$ only selects the extraneous root, which fails because the square root equals $1$ while the right side equals $-1$. The distractor stating both $-4$ and $6$ results from solving the quadratic correctly but failing to check for extraneous solutions introduced by squaring. The distractor $-6$ results from a sign error when solving $x - 6 = 0$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM240YF78', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'grid_in', E'The function $p$ is defined by $p(x) = (x - 13)^2 + 23$. What is the minimum value of $p(x)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '23', ARRAY['23'], E'The function $p(x) = (x - 13)^2 + 23$ is in vertex form $a(x - h)^2 + k$ with $a = 1 > 0$, $h = 13$, and $k = 23$. Since the coefficient of the squared term is positive, the parabola opens upward and the vertex represents the minimum. The minimum value is $k = 23$, occurring at $x = 13$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM246VXHY', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle has its center at $(-4, 3)$ and passes through the point $(2, -1)$. Which of the following is the equation of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$(x + 4)^2 + (y - 3)^2 = 52$"},{"key":"B","text":"$(x - 4)^2 + (y + 3)^2 = 52$"},{"key":"C","text":"$(x + 4)^2 + (y - 3)^2 = 2\\sqrt{13}$"},{"key":"D","text":"$(x - 2)^2 + (y + 1)^2 = 52$"}]$lyceon_json$::jsonb, 'A', NULL, E'The radius is the distance from the center $(-4, 3)$ to the point $(2, -1)$: $r = \\sqrt{(2 - (-4))^2 + (-1 - 3)^2} = \\sqrt{36 + 16} = \\sqrt{52}$. The equation is $(x - (-4))^2 + (y - 3)^2 = (\\sqrt{52})^2$, which gives $(x + 4)^2 + (y - 3)^2 = 52$. The equation $(x - 4)^2 + (y + 3)^2 = 52$ uses wrong signs for the center coordinates. The equation $(x + 4)^2 + (y - 3)^2 = 2\\sqrt{13}$ uses the radius $\\sqrt{52} = 2\\sqrt{13}$ instead of its square $r^2 = 52$. The equation $(x - 2)^2 + (y + 1)^2 = 52$ incorrectly uses the given point $(2, -1)$ as the center.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24DDSLE', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A triangle has a base of $14$ centimeters and a height of $11$ centimeters. What is the area of the triangle, in square centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$50$"},{"key":"B","text":"$70$"},{"key":"C","text":"$77$"},{"key":"D","text":"$154$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a triangle is $\\frac{1}{2} \\times \\text{base} \\times \\text{height} = \\frac{1}{2} \\times 14 \\times 11 = 77$ square centimeters. The value $154$ results from computing $14 \\times 11 = 154$ without applying the $\\frac{1}{2}$ factor. The value $70$ results from an arithmetic slip, such as misreading the height as $10$ and computing $\\frac{1}{2} \\times 14 \\times 10 = 70$. The value $50$ results from applying a wrong formula, such as computing the perimeter-related quantity $(14 + 11) \\times 2 = 50$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24XKT9C', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A company''s revenue was $240{,}000$ dollars in the first quarter. Revenue increased by $22\\%$ in the second quarter and then decreased by $35\\%$ in the third quarter. What was the revenue, in dollars, in the third quarter?', NULL, $lyceon_json$[{"key":"A","text":"$190{,}320$"},{"key":"B","text":"$208{,}800$"},{"key":"C","text":"$240{,}000$"},{"key":"D","text":"$292{,}800$"}]$lyceon_json$::jsonb, 'A', NULL, E'Second quarter revenue is $240{,}000 \\times 1.22 = 292{,}800$ dollars. Third quarter revenue after a $35\\%$ decrease is $292{,}800 \\times 0.65 = 190{,}320$ dollars. The value $208{,}800$ results from applying only the net percentage change of $22\\% - 35\\% = -13\\%$ to the original: $240{,}000 \\times 0.87 = 208{,}800$, which incorrectly assumes percentage changes are additive. The value $240{,}000$ assumes the increase and decrease cancel out, leaving revenue unchanged. The value $292{,}800$ is the second quarter revenue, reflecting a failure to apply the third quarter decrease.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM252V7HV', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{27x^6 - 8}{3x^2 - 2}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$9x^4 - 6x^2 + 4$"},{"key":"B","text":"$9x^4 + 6x^2 + 4$"},{"key":"C","text":"$9x^4 - 4$"},{"key":"D","text":"$9x^4 + 4$"}]$lyceon_json$::jsonb, 'B', NULL, E'Recognize that $27x^6 = (3x^2)^3$ and $8 = 2^3$, so the numerator is a difference of cubes: $a^3 - b^3 = (a - b)(a^2 + ab + b^2)$ with $a = 3x^2$ and $b = 2$. This gives $27x^6 - 8 = (3x^2 - 2)(9x^4 + 6x^2 + 4)$. Dividing by $(3x^2 - 2)$ yields $9x^4 + 6x^2 + 4$. The distractor $9x^4 - 6x^2 + 4$ results from a sign error, using the sum-of-cubes pattern $a^2 - ab + b^2$ instead of the difference-of-cubes pattern $a^2 + ab + b^2$, which negates the middle term. The distractor $9x^4 - 4$ comes from a concept gap, treating the expression as a difference of squares $(3x^2)^2 - 2^2$ instead of a difference of cubes, and omitting the middle term entirely. The distractor $9x^4 + 4$ results from partial reasoning, correctly identifying the first and last terms of the quotient but dropping the middle term $6x^2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM259FGZ6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A data set of $11$ values has a mean of $58$ and a median of $54$. The largest value in the data set, which is $97$, is replaced by $113$. Which of the following correctly describes the effect on the mean and median?', NULL, $lyceon_json$[{"key":"A","text":"The mean increases by $\\frac{16}{11}$ and the median stays the same."},{"key":"B","text":"Both the mean and median increase by $\\frac{16}{11}$."},{"key":"C","text":"The mean increases by $16$ and the median stays the same."},{"key":"D","text":"Both the mean and median stay the same."}]$lyceon_json$::jsonb, 'A', NULL, E'Replacing $97$ with $113$ increases the sum by $113 - 97 = 16$. The original sum is $11 \\times 58 = 638$, and the new sum is $654$. The new mean is $\\frac{654}{11} = 58 + \\frac{16}{11} \\approx 59.45$, an increase of $\\frac{16}{11}$. The median is the $6$th value in the ordered list. Since $97$ was the largest value and was replaced by an even larger value ($113$), the $6$th value in the ordered list is unchanged, so the median remains $54$. The claim that both increase by $\\frac{16}{11}$ incorrectly assumes that changing the largest value shifts the middle of the distribution. The claim that the mean increases by $16$ confuses the change in the sum with the change in the mean, forgetting to divide by $11$. The claim that both stay the same fails to account for the effect on the sum and therefore the mean.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25UFIIE', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A bakery produces muffins and scones. Each muffin uses $4$ ounces of flour and $2$ ounces of sugar. Each scone uses $6$ ounces of flour and $3$ ounces of sugar. The bakery has at most $78$ ounces of flour and at most $51$ ounces of sugar available each morning. If the bakery makes $9$ muffins, what is the maximum number of whole scones it can produce that same morning?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$8$"},{"key":"C","text":"$7$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $s$ represent the number of scones. The flour constraint is $4(9) + 6s \\leq 78$, which simplifies to $36 + 6s \\leq 78$, giving $6s \\leq 42$, so $s \\leq 7$. The sugar constraint is $2(9) + 3s \\leq 51$, which simplifies to $18 + 3s \\leq 51$, giving $3s \\leq 33$, so $s \\leq 11$. The binding constraint is flour, limiting production to $7$ scones. The value $11$ comes from applying only the sugar constraint and ignoring the flour constraint entirely. The value $8$ results from computing $78 - 36 = 42$ and dividing by $5$ instead of $6$, yielding $8.4$ and rounding down. The value $5$ arises from swapping the flour requirements for muffins and scones, using $6(9) + 4s \\leq 78$, which gives $54 + 4s \\leq 78$ and $s \\leq 6$, then further underestimating.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26AUCYC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A researcher wants to determine whether a new fertilizer increases tomato yield. She randomly assigns 60 tomato plants to two groups: one group receives the new fertilizer and the other receives no fertilizer. After 8 weeks, she measures the yield. What type of study is this?', NULL, $lyceon_json$[{"key":"A","text":"An experiment, because a treatment is imposed on randomly assigned groups"},{"key":"B","text":"An observational study, because the researcher measures an existing outcome"},{"key":"C","text":"A survey, because data is collected from a sample of plants"},{"key":"D","text":"An observational study, because no control group is used"}]$lyceon_json$::jsonb, 'A', NULL, E'Because the researcher randomly assigns plants to groups and imposes a treatment (fertilizer vs. no fertilizer), this is an experiment. Calling it an observational study because it measures an existing outcome ignores the key feature: the researcher actively manipulates the treatment variable rather than merely observing. Calling it a survey confuses data collection with study design; surveys collect self-reported data from people, which does not apply to plants receiving treatments. Claiming there is no control group is factually wrong, since the group receiving no fertilizer serves as the control.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26DB3V7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A polling organization surveys a random sample of 1,100 adults in a state and reports that 39% support a proposed tax change, with a margin of error of 3 percentage points at a 95% confidence level. A local newspaper claims that since 39% is less than 50%, the majority of adults in the state oppose the tax change. Which of the following is the most accurate critique of the newspaper''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The confidence interval (36% to 42%) does not include 50%, so the claim that a majority opposes is supported by the data."},{"key":"B","text":"The claim is unjustified because some respondents may have no opinion, so those who oppose may not constitute a majority."},{"key":"C","text":"The claim is valid only if the sample was stratified by age and income."},{"key":"D","text":"The margin of error is too large to draw any conclusions about voter opinion."}]$lyceon_json$::jsonb, 'B', NULL, E'The newspaper assumes that everyone who does not support the tax change opposes it. However, some respondents may be undecided or have no opinion, so 61% not supporting does not mean 61% actively oppose. Without knowing the breakdown between opposition and no opinion, the claim that a majority opposes is unjustified. The observation that the confidence interval (36% to 42%) excludes 50% confirms that fewer than half support the change, but this does not establish that a majority opposes it, since non-support includes undecided respondents. Requiring stratification by age and income conflates sampling methodology with the logical flaw in the claim. Saying the margin of error is too large to draw any conclusion is incorrect, as a 3-point margin of error at 95% confidence from 1,100 respondents is standard and adequate for inference.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26Y6D3P', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'$$3x + 2y = 19$$ $$3x - 2y = 11$$ What is the value of $x$ in the solution to the system of equations above?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Adding the two equations eliminates $y$: $(3x + 2y) + (3x - 2y) = 19 + 11$, giving $6x = 30$, so $x = 5$. This can be verified by subtracting the second equation from the first: $(3x + 2y) - (3x - 2y) = 19 - 11$ gives $4y = 8$, so $y = 2$. Checking: $3(5) + 2(2) = 15 + 4 = 19$ and $3(5) - 2(2) = 15 - 4 = 11$, both correct.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28NGMH7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher models the relationship between daily screen time in hours, $x$, and a cognitive performance score, $y$, with the equation $y = -2.3x + 91$. At $x = 13$ hours, the observed cognitive performance score is $57.1$. What is the residual for this data point?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$4$"},{"key":"C","text":"$-61.1$"},{"key":"D","text":"$61.1$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted cognitive performance score at $x = 13$ is $y = -2.3(13) + 91 = -29.9 + 91 = 61.1$. The residual is defined as observed minus predicted: $57.1 - 61.1 = -4$. A negative residual indicates the model overpredicted the performance score at this screen time level. The value $4$ results from computing predicted minus observed ($61.1 - 57.1$), reversing the residual formula and getting the wrong sign. The value $-61.1$ arises from subtracting the predicted value from zero instead of from the observed value. The value $61.1$ is the predicted value itself, not the residual, reflecting a failure to compute the difference between observed and predicted values.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28UIQXC', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A printer starts a job with 1,730 sheets of paper loaded. It uses 37 sheets per minute during the job. Which function $p(t)$ gives the number of sheets remaining after $t$ minutes of printing?', NULL, $lyceon_json$[{"key":"A","text":"$p(t) = 1730 + 37t$"},{"key":"B","text":"$p(t) = 37t - 1730$"},{"key":"C","text":"$p(t) = 1730 - 37t$"},{"key":"D","text":"$p(t) = 1730 - \\frac{t}{37}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The printer begins with 1,730 sheets and consumes 37 sheets each minute, so the number remaining after $t$ minutes is $p(t) = 1730 - 37t$. The expression $1730 + 37t$ incorrectly adds sheets over time, as though the printer were producing paper rather than consuming it. The expression $37t - 1730$ reverses the initial amount and the rate term, yielding negative values for any $t$ less than about $47$ minutes. The expression $1730 - \\frac{t}{37}$ uses the reciprocal of the rate, treating the consumption as $1$ sheet every $37$ minutes rather than $37$ sheets every minute.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29IP8B0', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = 3x^2 + 42x + 151$. The function $g$ is defined by $g(x) = f(x - 5) + 13$. What is the minimum value of $g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$17$"},{"key":"C","text":"$13$"},{"key":"D","text":"$-9$"}]$lyceon_json$::jsonb, 'B', NULL, E'First, rewrite $f(x)$ in vertex form by completing the square: $f(x) = 3(x^2 + 14x) + 151 = 3(x^2 + 14x + 49 - 49) + 151 = 3(x + 7)^2 - 147 + 151 = 3(x + 7)^2 + 4$. The minimum value of $f$ is $4$, occurring at $x = -7$. Now, $g(x) = f(x - 5) + 13 = 3((x - 5) + 7)^2 + 4 + 13 = 3(x + 2)^2 + 17$. Since $(x + 2)^2 \\geq 0$, the minimum of $g$ is $17$, occurring at $x = -2$. The distractor $4$ comes from partial reasoning, finding the minimum of $f$ but neglecting the vertical shift of $+13$ in the definition of $g$. The distractor $13$ comes from misreading the question, reporting only the added constant $13$ without accounting for the minimum value of $f$. The distractor $-9$ results from a sign error, computing $4 - 13 = -9$ instead of $4 + 13 = 17$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AO1GKU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A biologist records the average weekly rainfall in centimeters, $x$, and the number of amphibian sightings in a wetland reserve, $y$. The equation of the line of best fit is $y = 4.6x + 13$. Which of the following is the best interpretation of the number $4.6$ in this equation?', NULL, $lyceon_json$[{"key":"A","text":"For each one-centimeter increase in average weekly rainfall, the predicted number of amphibian sightings increases by $4.6$."},{"key":"B","text":"For each one-centimeter increase in average weekly rainfall, the predicted number of amphibian sightings decreases by $4.6$."},{"key":"C","text":"When the average weekly rainfall is $0$ centimeters, the predicted number of amphibian sightings is $4.6$."},{"key":"D","text":"When $4.6$ amphibian sightings are recorded, the predicted average weekly rainfall is $0$ centimeters."}]$lyceon_json$::jsonb, 'A', NULL, E'In the equation $y = 4.6x + 13$, the coefficient $4.6$ is the slope, which represents the predicted change in $y$ for each unit increase in $x$. In context, for each one-centimeter increase in average weekly rainfall, the predicted number of amphibian sightings increases by $4.6$. The interpretation that sightings decrease by $4.6$ per centimeter incorrectly assigns a negative direction to a positive slope. The interpretation that $4.6$ represents the predicted sightings at $0$ centimeters of rainfall confuses the slope with the $y$-intercept, which is $13$. The interpretation involving $4.6$ sightings and $0$ centimeters reverses the roles of the independent and dependent variables and misidentifies the meaning of the slope.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AXST70', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g$ is defined by $g(x) = 3 \\cdot 2^{x + 4} - 17$. Which of the following describes the range of $g$?', NULL, $lyceon_json$[{"key":"A","text":"All real numbers greater than $-17$"},{"key":"B","text":"All real numbers greater than or equal to $-17$"},{"key":"C","text":"All real numbers greater than $4$"},{"key":"D","text":"All real numbers"}]$lyceon_json$::jsonb, 'A', NULL, E'The base exponential $2^{x + 4}$ is always positive for all real $x$, approaching $0$ as $x \\to -\\infty$ but never equaling $0$. Multiplying by $3$ keeps it positive: $3 \\cdot 2^{x + 4} > 0$. Subtracting $17$ shifts the output down, so $g(x) > -17$ for all $x$, but $g(x)$ never equals $-17$. Therefore the range is all real numbers greater than $-17$. The choice stating greater than or equal to $-17$ incorrectly includes $-17$, which would require $3 \\cdot 2^{x + 4} = 0$, an impossibility since exponential functions with a positive base never equal zero. The choice stating greater than $4$ confuses the horizontal shift parameter in the exponent with the vertical asymptote. The choice stating all real numbers ignores that exponential functions produce only positive outputs before the vertical shift, so values at or below $-17$ are unreachable.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B2GAX0', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'$$kx + 4y = 31$$ $$6x + 8y = 53$$ In the system of equations above, $k$ is a constant. If the system has no solution, what is the value of $k$ ?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$\\frac{8}{3}$"},{"key":"C","text":"$-3$"},{"key":"D","text":"$\\frac{3}{2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'A system of two linear equations has no solution when the lines are parallel but not identical. This requires the ratios of the coefficients of $x$ and $y$ to be equal while the ratio of the constants differs. Setting $\\frac{k}{6} = \\frac{4}{8}$ gives $\\frac{k}{6} = \\frac{1}{2}$, so $k = 3$. Checking the constants: $\\frac{31}{53} \\neq \\frac{1}{2}$ (since $\\frac{1}{2} = 0.5$ and $\\frac{31}{53} \\approx 0.585$), confirming the system is inconsistent when $k = 3$. The value $\\frac{8}{3}$ results from incorrectly setting $\\frac{k}{6} = \\frac{8}{4}$ instead of $\\frac{4}{8}$, reversing the ratio of the $y$-coefficients and then solving. The value $-3$ introduces a spurious negative sign when solving for $k$, as if the equations required opposite-sign coefficients for parallelism. The value $\\frac{3}{2}$ comes from computing the ratio $\\frac{6}{4} = \\frac{3}{2}$ and taking the ratio itself as the answer rather than solving $\\frac{k}{6} = \\frac{1}{2}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BA2NWI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $6$. What is the area of a sector of this circle with a central angle of $60°$?', NULL, $lyceon_json$[{"key":"A","text":"$2\\pi$"},{"key":"B","text":"$6\\pi$"},{"key":"C","text":"$12\\pi$"},{"key":"D","text":"$36\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a sector is $\\frac{\\theta}{360°} \\times \\pi r^2 = \\frac{60°}{360°} \\times \\pi(6)^2 = \\frac{1}{6} \\times 36\\pi = 6\\pi$. The value $2\\pi$ results from computing the arc length $\\frac{60°}{360°} \\times 2\\pi(6) = 2\\pi$ instead of the sector area. The value $12\\pi$ results from an arithmetic error such as using $\\frac{1}{3}$ instead of $\\frac{1}{6}$ as the fraction of the circle. The value $36\\pi$ results from computing the full circle area $\\pi r^2 = 36\\pi$ without applying the sector fraction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CNHCPY', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'$$4x + 7y = 47$$ $$6x - 7y = -17$$ What is the value of $3x + 2y$ for the solution $(x, y)$ to the system of equations above?', NULL, $lyceon_json$[{"key":"A","text":"$19$"},{"key":"B","text":"$8$"},{"key":"C","text":"$20$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding the two equations eliminates $y$: $(4x + 7y) + (6x - 7y) = 47 + (-17)$, giving $10x = 30$, so $x = 3$. Substituting into the first equation: $4(3) + 7y = 47$ gives $12 + 7y = 47$, so $7y = 35$ and $y = 5$. Therefore $3x + 2y = 3(3) + 2(5) = 9 + 10 = 19$. The value $8$ results from computing $x + y = 3 + 5 = 8$ instead of the requested expression $3x + 2y$, solving correctly but evaluating the wrong combination. The value $20$ comes from an arithmetic slip such as computing $2(5)$ as $11$ instead of $10$, yielding $9 + 11 = 20$. The value $11$ results from misreading the requested expression as $2x + y$ instead of $3x + 2y$, giving $2(3) + 5 = 11$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E6X3JI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'grid_in', E'A factory uses $37$ kilograms of copper for every $8$ kilograms of zinc in a particular alloy. If the factory has $259$ kilograms of copper available and unlimited zinc, how many kilograms of zinc are needed to use all the copper?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '56', ARRAY['56'], E'The ratio of copper to zinc is $37:8$. Let $z$ be the kilograms of zinc needed. Then $\\frac{37}{8} = \\frac{259}{z}$, which gives $z = \\frac{259 \\times 8}{37} = \\frac{2{,}072}{37} = 56$ kilograms. A common error is to divide $259$ by $8$ instead of setting up the proportion correctly, yielding $32.375$. Another error is to multiply $259 \\times \\frac{37}{8}$, which inverts the ratio and computes how much copper would pair with $259$ kg of zinc.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EBLVVG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'A ladder leans against a vertical wall, making an angle of $71°$ with the ground. If the foot of the ladder is $3.2$ meters from the base of the wall, what is the length of the ladder, to the nearest tenth of a meter?', NULL, $lyceon_json$[{"key":"A","text":"$3.4$"},{"key":"B","text":"$9.3$"},{"key":"C","text":"$9.8$"},{"key":"D","text":"$1.0$"}]$lyceon_json$::jsonb, 'C', NULL, E'The ladder forms the hypotenuse of a right triangle. The distance from the wall ($3.2$ m) is the adjacent side to the $71°$ angle. Using $\\cos(71°) = \\frac{3.2}{L}$, the ladder length is $L = \\frac{3.2}{\\cos(71°)} = \\frac{3.2}{0.3256} \\approx 9.8$ meters. The value $3.4$ comes from dividing by $\\sin(71°)$ instead of $\\cos(71°)$: $\\frac{3.2}{0.9455} \\approx 3.4$. The value $9.3$ comes from computing $3.2 \\times \\tan(71°) \\approx 9.3$, which gives the wall height rather than the ladder length. The value $1.0$ comes from multiplying $3.2 \\times \\cos(71°) \\approx 1.0$, reversing the operation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EKLMKW', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The linear function $h$ is defined by $h(x) = -7x + 23$. A new function $k$ is defined by $k(x) = h(2x - 3)$. What is the $y$-intercept of the graph of $y = k(x)$ in the $xy$-plane?', NULL, $lyceon_json$[{"key":"A","text":"$-44$"},{"key":"B","text":"$2$"},{"key":"C","text":"$23$"},{"key":"D","text":"$44$"}]$lyceon_json$::jsonb, 'D', NULL, E'Substituting $2x - 3$ into $h$ gives $k(x) = h(2x - 3) = -7(2x - 3) + 23 = -14x + 21 + 23 = -14x + 44$. The $y$-intercept occurs at $x = 0$, giving $k(0) = 44$. The value $-44$ results from a sign error, negating the correct intercept. The value $2$ comes from an arithmetic slip of subtracting $21$ from $23$ instead of adding, computing $23 - 21 = 2$. The value $23$ comes from using the $y$-intercept of the original function $h$ without performing the composition, ignoring the inner function $2x - 3$ entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ERLF8G', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In right triangle $PQR$, angle $R = 90°$, $PR = 6$, and $QR = 11$. What is the value of $\\tan(Q)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{6}{11}$"},{"key":"B","text":"$\\frac{11}{6}$"},{"key":"C","text":"$\\frac{6}{\\sqrt{157}}$"},{"key":"D","text":"$\\frac{11}{\\sqrt{157}}$"}]$lyceon_json$::jsonb, 'A', NULL, E'In right triangle $PQR$ with the right angle at $R$, the side opposite angle $Q$ is $PR = 6$ and the side adjacent to angle $Q$ is $QR = 11$. Therefore $\\tan(Q) = \\frac{\\text{opposite}}{\\text{adjacent}} = \\frac{6}{11}$. The value $\\frac{11}{6}$ results from inverting the tangent ratio (using adjacent over opposite). The value $\\frac{6}{\\sqrt{157}}$ results from computing $\\sin(Q)$ instead of $\\tan(Q)$, using the hypotenuse $\\sqrt{6^2 + 11^2} = \\sqrt{157}$. The value $\\frac{11}{\\sqrt{157}}$ results from computing $\\cos(Q)$ instead of $\\tan(Q)$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FD4BQ0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A hollow cylindrical pipe has an outer radius of $6$ cm, an inner radius of $4$ cm, and a length of $21$ cm. What is the volume of the material making up the pipe, in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$84\\pi$"},{"key":"B","text":"$336\\pi$"},{"key":"C","text":"$420\\pi$"},{"key":"D","text":"$756\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The volume of the pipe material is the difference between the outer and inner cylinder volumes: $V = \\pi R^2 h - \\pi r^2 h = \\pi(R^2 - r^2)h = \\pi(36 - 16)(21) = \\pi(20)(21) = 420\\pi$ cubic centimeters. The value $84\\pi$ results from incorrectly subtracting the radii first and then squaring: $\\pi(6 - 4)^2(21) = \\pi(4)(21) = 84\\pi$. The value $336\\pi$ results from computing only the inner cylinder volume $\\pi(4)^2(21) = 336\\pi$, misidentifying it as the pipe material. The value $756\\pi$ results from computing only the outer cylinder volume $\\pi(6)^2(21) = 756\\pi$, ignoring the hollow interior.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FFDCSZ', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{x^2 + 13x + 36}{x^2 - 16}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x + 12}{x - 4}$"},{"key":"B","text":"$\\frac{x + 9}{x + 4}$"},{"key":"C","text":"$\\frac{x + 9}{x - 4}$"},{"key":"D","text":"$\\frac{x + 4}{x - 4}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Factor the numerator: $x^2 + 13x + 36 = (x + 9)(x + 4)$, since $9 + 4 = 13$ and $9 \\times 4 = 36$. Factor the denominator: $x^2 - 16 = (x - 4)(x + 4)$. Cancel the common factor $(x + 4)$: $\\frac{(x + 9)(x + 4)}{(x - 4)(x + 4)} = \\frac{x + 9}{x - 4}$. The distractor $\\frac{x + 12}{x - 4}$ comes from an arithmetic slip when factoring the numerator, incorrectly using $12$ and $3$ instead of $9$ and $4$ (since $12 + 3 = 15 \\neq 13$). The distractor $\\frac{x + 9}{x + 4}$ results from a sign error when factoring the denominator, writing $(x + 4)(x + 4)$ instead of $(x - 4)(x + 4)$, so the wrong factor cancels. The distractor $\\frac{x + 4}{x - 4}$ comes from partial reasoning, cancelling the $(x + 9)$ factor from the numerator against nothing instead of cancelling the common $(x + 4)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FVQ3MB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'A farmer''s crop yield increased by $18\\%$ from last year to this year. If this year''s yield was $47{,}790$ bushels, what was last year''s yield, in bushels?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '40500', ARRAY['40500'], E'Let last year''s yield be $y$. After an $18\\%$ increase, the yield is $1.18y$. Setting $1.18y = 47{,}790$ gives $y = \\frac{47{,}790}{1.18} = 40{,}500$ bushels. A common error is to subtract $18\\%$ of $47{,}790$ from $47{,}790$: $47{,}790 \\times 0.18 = 8{,}602.2$, giving $47{,}790 - 8{,}602.2 = 39{,}187.8$, which incorrectly applies the percentage to the final value rather than the original. Another error is to divide by $0.18$ instead of $1.18$, yielding an unreasonably large number.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GLVP9P', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ is defined by the equation $5x - 3y = 21$. Line $q$ is perpendicular to line $p$ and passes through the point $(10, 7)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$-13$"},{"key":"B","text":"$1$"},{"key":"C","text":"$7$"},{"key":"D","text":"$13$"}]$lyceon_json$::jsonb, 'D', NULL, E'Rewriting line $p$ in slope-intercept form: $5x - 3y = 21$ gives $y = \\frac{5}{3}x - 7$, so the slope of line $p$ is $\\frac{5}{3}$. A line perpendicular to $p$ has slope $-\\frac{3}{5}$. Using point-slope form with $(10, 7)$: $y - 7 = -\\frac{3}{5}(x - 10)$, which gives $y - 7 = -\\frac{3}{5}x + 6$, so $y = -\\frac{3}{5}x + 13$. The $y$-intercept is $13$. The value $-13$ results from a sign error, negating the correct intercept. The value $1$ comes from using slope $\\frac{3}{5}$ (the reciprocal without negating), giving $y - 7 = \\frac{3}{5}(x - 10) = \\frac{3}{5}x - 6$, so $y = \\frac{3}{5}x + 1$ with intercept $1$. The value $7$ comes from reporting the $y$-coordinate of the given point as the $y$-intercept without performing any calculation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GZPRZV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A rectangular box has a length of $11$ inches, a width of $3$ inches, and a total surface area of $262$ square inches. What is the volume of the box, in cubic inches?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '231', ARRAY['231'], E'The surface area of a rectangular box is $SA = 2(lw + lh + wh)$. Substituting the known values: $262 = 2(11 \\cdot 3 + 11h + 3h) = 2(33 + 14h)$. Dividing both sides by $2$: $131 = 33 + 14h$. Solving: $14h = 98$, so $h = 7$. The volume is $V = lwh = 11 \\times 3 \\times 7 = 231$ cubic inches. Common errors include using the wrong surface area formula (such as omitting the factor of $2$), solving for $h$ but then reporting $h = 7$ instead of the volume, or setting up the equation with only some pairs of faces rather than all three.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ITNKP4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A ceramics workshop mixes feldspar and silica in a ratio of $7:11$ by weight. Feldspar costs $3.40$ dollars per kilogram and silica costs $1.80$ dollars per kilogram. What is the cost, in dollars per kilogram, of the mixture?', NULL, $lyceon_json$[{"key":"A","text":"$2.42$"},{"key":"B","text":"$2.60$"},{"key":"C","text":"$5.20$"},{"key":"D","text":"$2.78$"}]$lyceon_json$::jsonb, 'A', NULL, E'In $18$ kilograms of mixture ($7 + 11$), the cost of feldspar is $7 \\times 3.40 = 23.80$ dollars and the cost of silica is $11 \\times 1.80 = 19.80$ dollars. The total cost is $23.80 + 19.80 = 43.60$ dollars for $18$ kilograms, so the cost per kilogram is $\\frac{43.60}{18} \\approx 2.42$ dollars. The value $2.60$ results from taking the simple average $\\frac{3.40 + 1.80}{2} = 2.60$ instead of using the weighted average based on the ratio. The value $5.20$ comes from adding the two unit prices $3.40 + 1.80 = 5.20$ without weighting or dividing by the total weight. The value $2.78$ arises from reversing the ratio weights, assigning $11$ parts to feldspar and $7$ parts to silica: $\\frac{11 \\times 3.40 + 7 \\times 1.80}{18} = \\frac{37.40 + 12.60}{18} = \\frac{50.00}{18} \\approx 2.78$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IWGFQ2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'In a class of 34 students, 19 play soccer, 13 play tennis, and 5 play both soccer and tennis. If a student is chosen at random, what is the probability that the student plays soccer or tennis?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{27}{34}$"},{"key":"B","text":"$\\frac{32}{34}$"},{"key":"C","text":"$\\frac{19}{34}$"},{"key":"D","text":"$\\frac{22}{34}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using the inclusion-exclusion principle, the number of students who play soccer or tennis is 19 + 13 - 5 = 27. The probability is 27/34. The value 32/34 results from adding 19 + 13 without subtracting the 5 students who play both, double-counting them. The value 19/34 considers only soccer players, ignoring those who play tennis but not soccer. The value 22/34 results from an arithmetic error such as computing 19 + 13 - 5 as 22 instead of 27.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IY1BD4', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'What value of $x$ satisfies the equation $11x + 29 = 128$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Subtracting $29$ from both sides gives $11x = 99$. Dividing both sides by $11$ yields $x = 9$. A common error is dividing $128$ by $11$ directly without first subtracting $29$, which gives a non-integer result. Another error is subtracting $29$ from one side only, leading to an incorrect equation.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IY4WU2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'The equation of a circle in the $xy$-plane is $x^2 + y^2 - 10x + 8y + 5 = 0$. A chord of this circle lies along the line $y = x - 1$. What is the length of this chord?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'First, rewrite the circle equation by completing the square: $(x^2 - 10x + 25) + (y^2 + 8y + 16) = -5 + 25 + 16$, which gives $(x - 5)^2 + (y + 4)^2 = 36$. The center is $(5, -4)$ and the radius is $6$. Next, find the distance from the center to the line $y = x - 1$, rewritten as $x - y - 1 = 0$. The distance is $d = \\frac{|5 - (-4) - 1|}{\\sqrt{1^2 + (-1)^2}} = \\frac{|8|}{\\sqrt{2}} = 4\\sqrt{2}$. The half-chord length is $\\sqrt{r^2 - d^2} = \\sqrt{36 - 32} = \\sqrt{4} = 2$, so the full chord length is $2 \\times 2 = 4$. Common errors include forgetting to complete the square correctly, using the wrong distance formula for a point to a line, or confusing the half-chord with the full chord length.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IYVP6M', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'grid_in', E'The line of best fit for a data set is given by $y = 2.7x + 8.3$. What is the predicted value of $y$ when $x = 7$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '27.2', ARRAY['136/5', '27.2'], E'Substituting $x = 7$ into the equation gives $y = 2.7(7) + 8.3 = 18.9 + 8.3 = 27.2$. A common error is to forget the $y$-intercept, giving $18.9$ alone. Another error is to add $2.7 + 7 + 8.3 = 18$ instead of multiplying the slope by $x$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JA1I4K', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of $x$ satisfies the inequality $7x - 11 < 38$ ?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$8$"},{"key":"C","text":"$6$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding $11$ to both sides of $7x - 11 < 38$ gives $7x < 49$. Dividing both sides by $7$ yields $x < 7$. Among the choices, only $6$ satisfies this strict inequality. The value $7$ fails because $7(7) - 11 = 38$, which is not strictly less than $38$. The value $8$ results from an arithmetic slip such as computing $38 + 11 = 49$ but then dividing by $7$ and rounding up to the next integer. The value $9$ reflects ignoring the coefficient entirely and treating the inequality as $x - 11 < 38$, which would give $x < 49$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L6S89T', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'A data set of $9$ values has a mean of $52$. When four new values, $29$, $47$, $63$, and $82$, are added to the data set, what is the mean of the resulting $13$ values?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '53', ARRAY['53'], E'The sum of the original $9$ values is $9 \\times 52 = 468$. Adding $29$, $47$, $63$, and $82$ gives a new sum of $468 + 29 + 47 + 63 + 82 = 689$. The mean of the $13$ values is $\\frac{689}{13} = 53$. A common error is to average the four new values with the old mean: $\\frac{52 + 29 + 47 + 63 + 82}{5} = 54.6$, which does not properly weight by the number of values in each group. Another error is to divide by $9$ instead of $13$ after adding the new values, giving $\\frac{689}{9} \\approx 76.6$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M75C1P', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In a triangle, two of the interior angles measure $56°$ and $79°$. What is the measure, in degrees, of the third interior angle?', NULL, $lyceon_json$[{"key":"A","text":"$35$"},{"key":"B","text":"$45$"},{"key":"C","text":"$55$"},{"key":"D","text":"$135$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of a triangle is $180°$. The third angle is $180° - 56° - 79° = 45°$. The value $135$ results from adding the two given angles ($56 + 79 = 135$) without subtracting from $180°$, which is only a partial step. The value $35$ results from an arithmetic error when subtracting ($56 + 79 = 145$ instead of $135$, giving $180 - 145 = 35$). The value $55$ results from a sign or subtraction error in the final computation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N9SCFF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'If $x^2 + y^2 = 85$ and $x + y = 11$, what is the value of $xy$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$18$"},{"key":"C","text":"$36$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'B', NULL, E'Square both sides of $x + y = 11$ to get $(x + y)^2 = 121$, which expands to $x^2 + 2xy + y^2 = 121$. Since $x^2 + y^2 = 85$, substitute to get $85 + 2xy = 121$, so $2xy = 36$ and $xy = 18$. The distractor $7$ comes from partial reasoning, computing $(x + y)^2 - (x^2 + y^2) = 121 - 85 = 36$ but then taking the square root instead of dividing by $2$, yielding $\\sqrt{36} = 6$ — or from finding $x - y = 7$ and reporting that value instead of $xy$. The distractor $36$ results from an equation setup error, forgetting the factor of $2$ in the expansion and computing $xy = 121 - 85 = 36$ directly. The distractor $11$ comes from misreading the question and reporting the value of $x + y$ instead of $xy$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NV88DO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A survey of 200 employees found the following: 74 work remotely, 126 work on-site, 41 of the remote workers have been with the company for more than 5 years, and 58 of the on-site workers have been with the company for more than 5 years. Given that a randomly selected employee has been with the company for more than 5 years, what is the probability that the employee works remotely?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{41}{99}$"},{"key":"B","text":"$\\frac{41}{74}$"},{"key":"C","text":"$\\frac{41}{200}$"},{"key":"D","text":"$\\frac{58}{99}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of employees with more than 5 years is 41 + 58 = 99. The conditional probability that an employee works remotely given they have more than 5 years is 41/99. The value 41/74 incorrectly uses the total number of remote workers as the denominator rather than the total number of employees with more than 5 years, confusing P(>5 years | remote) with P(remote | >5 years). The value 41/200 uses the entire employee population as the denominator, calculating the joint probability rather than the conditional probability. The value 58/99 gives the probability that a 5+ year employee works on-site, not remotely, reversing the numerator.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PEOXME', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A bookstore sold $234$ books on Friday and $195$ books on Saturday. What is the percent decrease in the number of books sold from Friday to Saturday, rounded to the nearest whole percent?', NULL, $lyceon_json$[{"key":"A","text":"$17\\%$"},{"key":"B","text":"$20\\%$"},{"key":"C","text":"$39\\%$"},{"key":"D","text":"$83\\%$"}]$lyceon_json$::jsonb, 'A', NULL, E'The decrease is $234 - 195 = 39$ books. The percent decrease is $\\frac{39}{234} \\times 100 \\approx 16.67\\%$, which rounds to $17\\%$. The value $20\\%$ results from dividing the decrease by Saturday''s count instead of Friday''s: $\\frac{39}{195} = 20\\%$. The value $39\\%$ confuses the absolute decrease of $39$ books with the percent decrease. The value $83\\%$ computes $\\frac{195}{234} \\approx 83\\%$, which is the proportion of Friday''s sales that remained, not the percent decrease.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PGSBD9', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'What is the slope of the line represented by the equation $13x - 4y = 52$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{13}{4}$"},{"key":"B","text":"$\\frac{4}{13}$"},{"key":"C","text":"$\\frac{13}{4}$"},{"key":"D","text":"$13$"}]$lyceon_json$::jsonb, 'C', NULL, E'Rewriting in slope-intercept form: $13x - 4y = 52$ becomes $-4y = -13x + 52$, and dividing by $-4$ gives $y = \\frac{13}{4}x - 13$. The slope is $\\frac{13}{4}$. The value $-\\frac{13}{4}$ results from a sign error, neglecting that dividing $-13x$ by $-4$ produces a positive coefficient. The value $\\frac{4}{13}$ results from taking the reciprocal of the slope, confusing rise over run with run over rise. The value $13$ comes from reading the coefficient of $x$ in the original standard form without converting to slope-intercept form.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PP3VSF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains 11 red marbles, 7 blue marbles, and 3 green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{21}$"},{"key":"B","text":"$\\frac{7}{14}$"},{"key":"C","text":"$\\frac{3}{21}$"},{"key":"D","text":"$\\frac{11}{21}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of marbles is 11 + 7 + 3 = 21. The probability of selecting a blue marble is the number of blue marbles divided by the total: 7/21 (which simplifies to 1/3). The value 7/14 results from incorrectly using only the red and blue marbles as the total, ignoring the green marbles. The value 3/21 corresponds to selecting a green marble instead of blue. The value 11/21 corresponds to selecting a red marble instead of blue.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q4FWK4', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'What is the value of $x$ in the equation $$\\frac{2x + 7}{3} - \\frac{x - 1}{6} = \\frac{5x}{4}\\;?$$', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10/3', ARRAY['10/3', '3.333'], E'The least common multiple of $3$, $6$, and $4$ is $12$. Multiplying every term by $12$ gives $4(2x + 7) - 2(x - 1) = 3(5x)$. Distributing yields $8x + 28 - 2x + 2 = 15x$. Combining like terms on the left gives $6x + 30 = 15x$. Subtracting $6x$ from both sides yields $30 = 9x$, so $x = \\frac{30}{9} = \\frac{10}{3}$. A common error is distributing the negative sign incorrectly in $-2(x - 1)$, writing $-2x - 2$ instead of $-2x + 2$, which changes the constant to $26$ and gives $x = \\frac{26}{9}$. Another error is using $6$ instead of $12$ as the common denominator, which fails to clear all fractions.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q67MLY', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What value of $x$ satisfies the equation $\\frac{4x + 23}{5} = x + 1$?', NULL, $lyceon_json$[{"key":"A","text":"$-18$"},{"key":"B","text":"$18$"},{"key":"C","text":"$22$"},{"key":"D","text":"$28$"}]$lyceon_json$::jsonb, 'B', NULL, E'Multiplying both sides by $5$ gives $4x + 23 = 5x + 5$. Subtracting $4x$ from both sides yields $23 = x + 5$. Subtracting $5$ from both sides gives $x = 18$. The value $-18$ results from a sign error, negating the correct answer. The value $22$ comes from multiplying only the $x$ term on the right by $5$, producing $4x + 23 = 5x + 1$, which gives $x = 22$. The value $28$ results from an arithmetic slip of adding $23 + 5 = 28$ instead of subtracting $5$ from $23$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QYVLND', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = -17x + 83$. What is the value of $g(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$-134$"},{"key":"B","text":"$32$"},{"key":"C","text":"$66$"},{"key":"D","text":"$134$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 3$ gives $g(3) = -17(3) + 83 = -51 + 83 = 32$. The value $-134$ comes from subtracting $83$ instead of adding it, computing $-17(3) - 83 = -51 - 83 = -134$. The value $66$ results from an arithmetic slip of subtracting $17$ once rather than multiplying by $3$, computing $83 - 17 = 66$. The value $134$ comes from ignoring the negative sign on $17$, computing $17(3) + 83 = 51 + 83 = 134$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S664YK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The ages, in years, of $9$ participants in a workshop are listed below.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SNN8LN', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $3(2x^2 + 9x - 4) + 2(x^2 - 7x + 11)$?', NULL, $lyceon_json$[{"key":"A","text":"$8x^2 + 41x + 10$"},{"key":"B","text":"$4x^2 + 13x + 10$"},{"key":"C","text":"$8x^2 + 13x - 34$"},{"key":"D","text":"$8x^2 + 13x + 10$"}]$lyceon_json$::jsonb, 'D', NULL, E'Distributing the first term gives $6x^2 + 27x - 12$. Distributing the second term gives $2x^2 - 14x + 22$. Combining like terms: $(6 + 2)x^2 = 8x^2$, $(27 - 14)x = 13x$, and $-12 + 22 = 10$. The result is $8x^2 + 13x + 10$. The distractor $8x^2 + 41x + 10$ results from a sign error when distributing the $2$ to $-7x$, yielding $+14x$ instead of $-14x$ so that $27 + 14 = 41$. The distractor $4x^2 + 13x + 10$ comes from incorrectly computing the $x^2$ coefficient as $3 \\cdot 2 - 2 \\cdot 1 = 4$ instead of $3 \\cdot 2 + 2 \\cdot 1 = 8$, confusing addition with subtraction. The distractor $8x^2 + 13x - 34$ results from an arithmetic slip on the constants, computing $-12 - 22 = -34$ instead of $-12 + 22 = 10$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SOLG4G', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $ABC$, angle $BAC = 38°$ and angle $ABC = 97°$. Point $D$ lies on side $BC$ such that $AD$ bisects angle $BAC$. What is the measure, in degrees, of angle $ADC$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '116', ARRAY['116'], E'First, find angle $ACB = 180° - 38° - 97° = 45°$. Since $AD$ bisects angle $BAC$, angle $DAC = \\frac{38°}{2} = 19°$. In triangle $ADC$, the angles must sum to $180°$: angle $ADC = 180° - 19° - 45° = 116°$. A common error is using the full angle $BAC = 38°$ instead of the bisected angle $19°$ in triangle $ADC$, which would give $180° - 38° - 45° = 97°$. Another error is forgetting to find angle $ACB$ first and instead using the exterior angle theorem incorrectly.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UNRW05', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'Which of the following is equivalent to $-3(2x - 7) > 5x + 4$ ?', NULL, $lyceon_json$[{"key":"A","text":"$x > \\frac{17}{11}$"},{"key":"B","text":"$x < \\frac{17}{11}$"},{"key":"C","text":"$x < -\\frac{17}{11}$"},{"key":"D","text":"$x < \\frac{25}{11}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Distributing gives $-6x + 21 > 5x + 4$. Subtracting $5x$ from both sides yields $-11x + 21 > 4$. Subtracting $21$ from both sides gives $-11x > -17$. Dividing both sides by $-11$ and reversing the inequality sign yields $x < \\frac{17}{11}$. The result $x > \\frac{17}{11}$ comes from forgetting to flip the inequality direction when dividing by a negative number. The result $x < -\\frac{17}{11}$ arises from carrying a spurious negative sign through the final step, treating $\\frac{-17}{11}$ as the bound instead of $\\frac{17}{11}$. The result $x < \\frac{25}{11}$ comes from adding $21 + 4 = 25$ instead of subtracting $21 - 4 = 17$ when combining the constant terms.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V7ZRZH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 250 voters in a city found that 62% support a new library bond. The margin of error for the survey is 4 percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Between 58% and 66% of all voters in the city likely support the bond."},{"key":"B","text":"Exactly 62% of all voters in the city support the bond."},{"key":"C","text":"Between 62% and 66% of all voters in the city likely support the bond."},{"key":"D","text":"The survey is inaccurate because the margin of error is too large."}]$lyceon_json$::jsonb, 'A', NULL, E'A margin of error of 4 percentage points means the true population proportion is plausibly within 4 points above or below the sample estimate: 62% - 4% = 58% to 62% + 4% = 66%. The statement that exactly 62% support the bond treats the sample statistic as the exact population parameter, ignoring sampling variability. The range 62% to 66% applies the margin of error in only one direction, omitting the lower bound. Claiming the survey is inaccurate because of the margin of error misunderstands the purpose of reporting a margin of error, which quantifies uncertainty rather than indicating a flaw.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VPYIF6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of 400 residents in a town and finds that 47% prefer expanded bus routes. A second random sample of 900 residents from the same town finds that 51% prefer expanded bus routes. Which of the following best explains why the second sample is more likely to produce a confidence interval that contains the true population proportion?', NULL, $lyceon_json$[{"key":"A","text":"The larger sample size reduces the margin of error, producing a narrower and more precise interval."},{"key":"B","text":"The larger sample size guarantees the sample proportion equals the population proportion."},{"key":"C","text":"The larger sample eliminates all sampling bias."},{"key":"D","text":"The second sample's higher percentage is closer to 50%, making it more accurate."}]$lyceon_json$::jsonb, 'A', NULL, E'Increasing the sample size decreases the standard error and thus the margin of error, yielding a narrower confidence interval that is more precise. A larger sample does not guarantee the sample proportion equals the population proportion; sampling variability always exists regardless of sample size. A larger sample reduces random sampling error but does not eliminate systematic bias, which is a design issue unrelated to sample size. The closeness of 51% to 50% is coincidental and does not inherently make an estimate more accurate; precision depends on sample size and sampling method, not the value of the estimate itself.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y5ZEY1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'Researchers conduct a randomized controlled trial to test whether a new tutoring method improves standardized test scores. They recruit 300 volunteers from a single high school and randomly assign them to either the new tutoring method or traditional tutoring. After 12 weeks, students using the new method score an average of 37 points higher. Which of the following is a valid conclusion from this study?', NULL, $lyceon_json$[{"key":"A","text":"The new tutoring method likely caused the higher scores among the participants, but the results may not generalize to students at other schools."},{"key":"B","text":"The new tutoring method causes higher scores for all high school students."},{"key":"C","text":"No causal conclusion can be drawn because the participants were volunteers."},{"key":"D","text":"The results prove that traditional tutoring is ineffective."}]$lyceon_json$::jsonb, 'A', NULL, E'Random assignment of participants to treatment and control groups allows a causal inference: the new method likely caused the score improvement among these participants. However, since the sample consists of volunteers from a single school, the results cannot be generalized to all high school students. Claiming the method causes higher scores for all high school students overgeneralizes beyond the study population. While using volunteers does limit generalizability, the random assignment to groups within those volunteers still supports a causal conclusion about the treatment effect for the participants. Saying traditional tutoring is ineffective mischaracterizes the finding; a 37-point difference means the new method outperformed traditional tutoring, not that traditional tutoring produced no benefit.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZBBO5O', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A health agency observes that among 5,000 adults, those who drink green tea daily have lower rates of heart disease than those who do not. The agency concludes that drinking green tea reduces heart disease risk. Which of the following is the most significant flaw in the agency''s conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The study is observational, so confounding variables may explain the association rather than a causal effect of green tea."},{"key":"B","text":"The sample size of 5,000 is too small to detect a meaningful difference."},{"key":"C","text":"The study did not measure how much green tea each person consumed per day."},{"key":"D","text":"The conclusion is valid because the agency used a large and diverse sample."}]$lyceon_json$::jsonb, 'A', NULL, E'Because participants were not randomly assigned to drink or not drink green tea, this is an observational study. Confounding variables (such as overall diet, exercise habits, or socioeconomic status) may differ between the two groups and could explain the lower heart disease rate, making a causal claim unjustified. A sample of 5,000 is generally large enough for detecting meaningful health differences, so sample size is not the primary concern. While not measuring exact daily consumption is a limitation, it does not address the fundamental problem that correlation does not establish causation without random assignment. Claiming the conclusion is valid because of a large sample ignores the inability of observational studies to establish causation regardless of sample size.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20KMIHD', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in relation to the first?', E'Ethologist Kwame Boateng observed that captive African grey parrots housed in acoustically enriched environments—rooms with recorded birdsong, running water, and ambient forest sounds—produced a wider variety of vocalizations than parrots housed in standard laboratory settings. Boateng hypothesized that acoustic complexity stimulates the parrots'' vocal learning circuits, leading to greater repertoire diversity.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21LKW8L', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Marine biologists studying the migratory patterns of humpback whales in the Coral Sea have found that the animals follow remarkably ________ routes year after year, deviating by no more than a few kilometers from the paths recorded in previous seasons.', $lyceon_json$[{"key":"A","text":"consistent"},{"key":"B","text":"funded"},{"key":"C","text":"decorated"},{"key":"D","text":"noisy"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes whales following routes that barely change from year to year, deviating by only a few kilometers. "Consistent" means unchanging or steady, which directly fits the idea of repeating nearly identical paths. "Funded" relates to financial backing, which is incoherent when describing routes. "Decorated" means ornamented, which makes no sense applied to migratory paths. "Noisy" describes sound, which is irrelevant to the steadiness of a route.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW223A5UN', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'The fruit fly Drosophila melanogaster has been a staple of genetics research since Thomas Hunt Morgan''s experiments in the early twentieth century. Its genome is compact, its reproductive cycle is short, and colonies can be maintained inexpensively. [underlined] Despite these practical advantages, some researchers have recently questioned whether findings from Drosophila studies translate reliably to mammalian biology. [/underlined] This skepticism has prompted a wave of comparative studies pairing fly and mouse models to test the generalizability of key genetic pathways.', $lyceon_json$[{"key":"A","text":"It introduces a concern that motivates the research described afterward."},{"key":"B","text":"It provides historical background on the discovery of Drosophila as a model organism."},{"key":"C","text":"It summarizes the main conclusion reached by the comparative studies."},{"key":"D","text":"It lists the specific genetic pathways being investigated."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence raises the concern that Drosophila findings may not translate to mammalian biology, and the next sentence explains that this skepticism prompted comparative studies. Thus the underlined sentence introduces a concern that motivates the subsequent research. The choice claiming it provides historical background is wrong because historical context appears earlier in the passage, not in the underlined sentence. The choice claiming it summarizes conclusions of comparative studies is wrong because those studies are described as a response to the skepticism, and no conclusions are presented. The choice claiming it lists genetic pathways is wrong because no specific pathways are named in the underlined sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22AQ4X6', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The implications of the recent discovery by a team of paleontologists working in the Gobi Desert—that a previously unknown species of tyrannosaur roamed the region roughly sixty-eight million years ago—_______ still being debated by researchers who study Late Cretaceous ecosystems.', $lyceon_json$[{"key":"A","text":"are"},{"key":"B","text":"is"},{"key":"C","text":"has been"},{"key":"D","text":"was"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the sentence is "implications," a plural noun that requires the plural verb "are." The long dash-enclosed parenthetical—"that a previously unknown species of tyrannosaur roamed the region roughly sixty-eight million years ago"—and the intervening prepositional phrases ("of the recent discovery," "by a team of paleontologists") create substantial distance between the subject and its verb, tempting the reader to match the verb with a nearer singular noun such as "discovery," "team," or "species." The singular form "is" fails to agree with the plural subject "implications." The singular present-perfect form "has been" likewise does not agree with the plural subject. The singular past-tense form "was" both fails in agreement and incorrectly shifts the debate into the past, whereas the sentence indicates the debate is ongoing.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23KAQFE', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Geographer Rina Matsuda has proposed that urban sprawl in the American Southwest cannot be adequately explained by population growth alone. She points to zoning ordinances enacted between 1947 and 1963 that incentivized single-family developments over multifamily housing, arguing that these policies created a legal framework for low-density expansion regardless of demographic trends. Matsuda supports this claim by comparing Tucson, where such ordinances were widespread, with El Paso, which adopted mixed-use zoning earlier and experienced comparable population growth but significantly less outward sprawl.', $lyceon_json$[{"key":"A","text":"It presents a claim, explains the reasoning behind it, and offers a comparative example as support."},{"key":"B","text":"It describes two cities and then evaluates which one managed growth more effectively."},{"key":"C","text":"It traces the chronological history of zoning policy from 1947 to the present day."},{"key":"D","text":"It contrasts two competing theories of urban sprawl and endorses neither."}]$lyceon_json$::jsonb, 'A', NULL, E'The text first states Matsuda''s claim (sprawl is not explained by population growth alone), then explains her reasoning (zoning ordinances created a legal framework for low-density expansion), and finally compares Tucson and El Paso to support that claim. The choice describing two cities and evaluating growth management is wrong because the passage does not evaluate which city managed growth better; the comparison serves to support the zoning claim. The choice about tracing chronological history is wrong because the passage mentions a date range only as context for the ordinances, not as a chronological narrative extending to the present. The choice about contrasting two competing theories is wrong because the passage presents only Matsuda''s argument, not a second competing theory.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25BN4US', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the central claim of the text?', E'Political theorist Danielle Allen has argued that the standard account of the Declaration of Independence misreads its rhetorical architecture. Conventional commentary emphasizes the document''s second sentence—"We hold these truths to be self-evident"—as the philosophical centerpiece, treating individual rights as the Declaration''s animating concept. Allen contends, however, that such readings detach the sentence from the argumentative structure that surrounds it. She observes that the Declaration devotes far more space to a catalog of collective grievances against the Crown and to an account of repeated, failed petitions for redress. These sections, Allen argues, establish that legitimate political authority originates not in abstract principles alone but in a community''s sustained, practical effort to secure equitable treatment. Individual rights, on her reading, function as premises within a larger argument about collective political agency rather than serving as free-standing axioms.', $lyceon_json$[{"key":"A","text":"Allen maintains that the Declaration's argumentative structure subordinates individual rights to a broader case for collective political agency."},{"key":"B","text":"Allen demonstrates that the Declaration's list of grievances was intended as a legal brief rather than a philosophical argument."},{"key":"C","text":"Allen argues that conventional readings of the Declaration overemphasize collective grievances at the expense of the document's philosophical commitments."},{"key":"D","text":"Allen proposes that the Declaration's second sentence was a late addition that disrupted the document's original rhetorical coherence."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes Allen''s argument that individual rights in the Declaration function as premises within a larger argument about collective political agency, not as free-standing axioms. The answer that Allen subordinates individual rights to a broader case for collective political agency accurately reflects this central claim. The characterization of the grievances as a legal brief rather than a philosophical argument introduces a distinction the passage never makes; Allen treats them as part of a philosophical-rhetorical structure. The claim that conventional readings overemphasize collective grievances inverts Allen''s actual criticism, which is that conventional readings overemphasize individual rights while underreading the collective grievance sections. The suggestion that the second sentence was a late addition is entirely unsupported; Allen discusses how it is read, not when it was drafted.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2674RBM', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Conservators restoring a 17th-century Dutch still-life painting discovered that the artist had originally included a partially peeled lemon in the foreground, a motif common in vanitas paintings meant to symbolize the fleeting nature of earthly pleasures. At some point, however, the lemon was painted over with a neutral background tone. X-ray imaging revealed that the overpainting was done using pigments consistent with those available in the early 18th century, not the 17th century. This suggests that the alteration was not made by the original artist but ________', $lyceon_json$[{"key":"A","text":"by a later restorer or owner who chose to modify the composition after the artist's lifetime."},{"key":"B","text":"because the original pigments used for the lemon had deteriorated beyond recognition."},{"key":"C","text":"to increase the painting's monetary value by making it appear more modern in style."},{"key":"D","text":"by the artist's apprentice, who completed the painting after the artist abandoned it."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that the overpainting used pigments from the early 18th century, not the 17th century, which rules out the original artist. The most logical completion is that a later restorer or owner modified the composition after the artist''s lifetime, since the pigment evidence places the alteration in a later era. The suggestion about pigment deterioration does not logically follow from evidence about overpainting with later pigments; deterioration would not explain the addition of new paint. The claim about increasing monetary value introduces a speculative motive unsupported by anything in the text. The apprentice explanation is undermined by the century gap between the original work and the overpainting pigments; an apprentice would have used contemporary materials.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26QJK3Z', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'The architects of the Sámi Parliament building in Inari, Finland, drew heavily on the curved silhouettes of traditional lavvu dwellings when designing the structure''s roof. __________ the building''s ventilation system incorporates principles from centuries-old reindeer herding shelters, using passive airflow channels modeled on the smoke holes found in those structures.', $lyceon_json$[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"Similarly,"},{"key":"C","text":"Instead,"},{"key":"D","text":"Consequently,"}]$lyceon_json$::jsonb, 'B', NULL, E'The first sentence describes how the building''s roof design was inspired by traditional lavvu dwellings. The sentence after the blank describes a parallel case: the ventilation system also draws on traditional Sámi structures. Both sentences present examples of traditional construction influencing modern design. "Similarly," correctly signals this parallel relationship. "Nevertheless," incorrectly implies a concession or contrast between the two design choices. "Instead," wrongly suggests the ventilation approach replaced the roof design rather than complementing it. "Consequently," incorrectly frames the ventilation design as a result of the roof design, when they are independent instances of the same broader approach.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26THBNG', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW295IQXA', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a proposal for a municipal planning committee and wants to argue that the city should prioritize bioswale installation over conventional storm drains by contrasting their long-term costs and environmental performance. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29T2AVE', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'In a 2019 study of urban heat islands, climatologist Dr. Yael Tariq observed that planting mature shade trees along asphalt corridors could ________ surface temperatures by as much as eleven degrees Celsius during peak afternoon hours, a reduction she attributed primarily to transpiration rather than mere shade coverage.', $lyceon_json$[{"key":"A","text":"diminish"},{"key":"B","text":"multiply"},{"key":"C","text":"relocate"},{"key":"D","text":"broadcast"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that shade trees reduce surface temperatures by up to eleven degrees, calling this outcome a "reduction." "Diminish" means to make smaller or less, which directly matches the described decrease in temperature. "Multiply" means to increase in number or quantity, which is the opposite of the described effect. "Relocate" means to move to a different place, which is incoherent when applied to temperatures being lowered. "Broadcast" means to transmit widely, which has no logical connection to reducing temperatures.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BXE7NA', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'What can most reasonably be inferred from the text?', E'In a 2019 experiment, neurobiologist Kenji Doya and colleagues trained two groups of macaques on a decision-making task that required choosing between a guaranteed small reward and a variable larger reward whose probability shifted unpredictably across trials. One group received targeted pharmacological suppression of serotonin activity in the dorsal raphe nucleus before each session; the control group received a saline placebo. Both groups learned to track the shifting probabilities at comparable rates, but the serotonin-suppressed macaques abandoned the variable option significantly sooner during periods when its probability of paying out had temporarily declined. Notably, when the payout probability recovered, the serotonin-suppressed macaques were slower to return to the variable option than controls.', $lyceon_json$[{"key":"A","text":"Serotonin activity in the dorsal raphe nucleus likely contributes to an organism's capacity to tolerate short-term unfavorable outcomes while maintaining a longer-term adaptive strategy."},{"key":"B","text":"Suppression of serotonin activity impairs a macaque's fundamental ability to detect changes in reward probability over successive trials."},{"key":"C","text":"The dorsal raphe nucleus is the sole brain region responsible for regulating risk-tolerance behavior in primates."},{"key":"D","text":"Macaques with suppressed serotonin activity prefer guaranteed rewards because they cannot distinguish between different magnitudes of reward."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows that serotonin-suppressed macaques tracked shifting probabilities at comparable rates to controls (so detection ability was intact) but abandoned the variable option sooner during downturns and were slower to return when conditions improved. This pattern suggests serotonin helps organisms persist through short-term unfavorable stretches in pursuit of longer-term gains, supporting the inference about tolerating short-term setbacks while maintaining adaptive strategy. The claim that serotonin suppression impairs the ability to detect probability changes is directly contradicted by the passage, which states both groups learned to track shifting probabilities at comparable rates. The assertion that the dorsal raphe nucleus is the sole region responsible for risk tolerance goes far beyond the text, which tests only one region and draws no exclusivity claim. The explanation that serotonin-suppressed macaques cannot distinguish reward magnitudes is unsupported; the passage indicates they understood the options but shifted their tolerance for variability, not their perception of magnitude.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GESCBC', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'A historian argues that the construction of the Hejaz Railway (1900–1908) was motivated primarily by the Ottoman Empire''s desire to project military and administrative control over the Arabian Peninsula, rather than by the religious goal of easing the pilgrimage to Mecca. Which finding, if true, would most directly weaken this argument?', E'The Hejaz Railway, completed in segments between 1900 and 1908, connected Damascus to Medina across roughly 1,300 kilometers of arid terrain. Funded partly by donations from Muslims worldwide and partly by Ottoman state revenues, the railway dramatically reduced the pilgrimage journey from a grueling 40-day caravan trek to approximately 72 hours by rail. Ottoman Sultan Abdülhamid II publicly framed the project as a pious undertaking dedicated to facilitating the hajj. Military planners within the Ottoman government, however, recognized that the railway would also enable rapid troop deployment to regions that had resisted centralized authority.', $lyceon_json$[{"key":"A","text":"Ottoman treasury records show that over 60 percent of the railway's funding came from voluntary donations solicited exclusively through appeals to religious duty."},{"key":"B","text":"The railway's route followed existing caravan trails that had been used by pilgrims for centuries rather than a path optimized for accessing military garrisons."},{"key":"C","text":"Several European powers viewed the Hejaz Railway as a threat to their own colonial interests in the region and lobbied against its construction."},{"key":"D","text":"Ottoman military forces used the railway to transport troops during regional conflicts in the decade following its completion."}]$lyceon_json$::jsonb, 'B', NULL, E'The historian''s argument is that military-administrative control, not religious facilitation, was the primary motivation. The finding that the route followed centuries-old pilgrimage trails rather than a path optimized for reaching military garrisons directly weakens this claim by suggesting the design prioritized pilgrim convenience over strategic military access. The point about funding coming from religious-duty appeals addresses funding sources but does not directly counter the possibility that the Ottoman state pursued military goals while accepting religious donations; funding source and purpose are separable, making this only partial evidence. European opposition to the railway concerns external perceptions, not Ottoman motivations. Ottoman troop transport after completion shows the railway had military uses but does not address whether that was the primary motivation for building it, so it fails to weaken the claim.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H86OWF', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Anika Patel has spent over a decade studying the migration patterns of leatherback sea turtles in the eastern Pacific. Her research has revealed that these turtles travel distances exceeding 11,000 kilometers annually between nesting beaches in Costa Rica and foraging grounds near New Zealand. __________ Patel''s findings have prompted several coastal nations to establish new protected corridors along the turtles'' migratory routes.', $lyceon_json$[{"key":"A","text":"As a result,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"On the other hand,"},{"key":"D","text":"For instance,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes Patel''s research findings about leatherback turtle migration distances, and the sentence following the blank describes a consequence of those findings: coastal nations establishing protected corridors. The cause-and-effect relationship requires a result transition. "As a result," correctly signals that the protected corridors are a consequence of the research. "In contrast," and "On the other hand," incorrectly introduce an opposition that does not exist between the research and its policy outcome. "For instance," incorrectly treats the policy response as an example rather than a consequence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IFWO1P', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of pressed botanical specimens from the highlands of _______ over two hundred rare fern species, many of which were previously undocumented in the region''s ecological surveys.', $lyceon_json$[{"key":"A","text":"Borneo includes"},{"key":"B","text":"Borneo include"},{"key":"C","text":"Borneo are including"},{"key":"D","text":"Borneo have included"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the sentence is "collection," which is singular and requires a singular verb. The singular form "includes" correctly agrees with "collection." The plural form "include" incorrectly treats the subject as plural, likely reflecting a misidentification of the plural noun "specimens" or "highlands" as the subject. The plural progressive form "are including" makes the same subject-verb agreement error while also introducing an unnecessary progressive aspect. The plural perfect form "have included" again uses a plural verb with the singular subject "collection" and shifts the tense to present perfect without contextual justification.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J66BT1', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the archaeologist first examined the Lydian tomb complex in 2019, she noted that the foundation stones _______ significant weathering. In her most recent assessment, conducted last month, she observed that erosion has continued to degrade the structural integrity of the remaining walls.', $lyceon_json$[{"key":"A","text":"had undergone"},{"key":"B","text":"have undergone"},{"key":"C","text":"undergo"},{"key":"D","text":"would undergo"}]$lyceon_json$::jsonb, 'A', NULL, E'The past perfect form "had undergone" is required here because the weathering of the foundation stones occurred before the archaeologist''s 2019 examination—an event that is itself already in the past. The past perfect correctly establishes this sequence of two past events. The present perfect form "have undergone" incorrectly situates the weathering as extending to the present moment, conflicting with the past-tense narrative frame established by "first examined" and "she noted." The simple present form "undergo" is inconsistent with the past-tense context of the 2019 examination. The conditional form "would undergo" implies a hypothetical or future-in-the-past scenario, but the weathering had already occurred—it was not speculative or anticipated.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KSJ5T7', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Literary critic Fumiko Adeyemi has argued that the novelist Chadwick Osei does not merely depict social inequality in his fiction but actively ________ it, structuring his narratives so that the reading experience itself mirrors the disorientation and systemic exclusion faced by his protagonists.', $lyceon_json$[{"key":"A","text":"enacts"},{"key":"B","text":"catalogues"},{"key":"C","text":"ignores"},{"key":"D","text":"finances"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage contrasts merely depicting inequality with doing something more active: structuring narratives so the reading experience itself mirrors the disorientation of exclusion. "Enacts" means to perform or put into practice, capturing the idea that Osei does not just represent inequality but makes the reader experience it through form. "Catalogues" means to systematically list or record, which would describe a passive inventory of inequalities rather than the active, experiential reproduction the passage emphasizes. "Ignores" means to pay no attention to, which directly contradicts the passage''s claim that Osei engages deeply with inequality. "Finances" means to provide funding for, which is incoherent in the context of a novelist''s treatment of a theme.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L4U9UZ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Economists studying the adoption of mobile banking in rural sub-Saharan Africa have found that access to digital financial services correlates with higher household savings rates. However, a 2021 study of 14 villages in central Mozambique complicated this picture: households that adopted mobile banking did increase the frequency of their savings deposits, but their total accumulated savings after 18 months were not significantly different from those of non-adopting households. The researchers attributed this discrepancy to the fact that mobile banking also made it easier to ________', $lyceon_json$[{"key":"A","text":"withdraw and spend savings impulsively, offsetting the increase in deposit frequency."},{"key":"B","text":"conceal financial assets from household members who might otherwise claim a share."},{"key":"C","text":"transfer funds to formal banking institutions that charged higher account maintenance fees."},{"key":"D","text":"receive remittances from relatives in urban areas, inflating apparent savings figures."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents a puzzle: deposit frequency increased but total accumulated savings did not. For more frequent deposits to fail to produce higher totals, something must be draining accumulated funds at a comparable rate. The most logical completion is that mobile banking also facilitated easier withdrawals and impulsive spending, offsetting the deposit gains. The suggestion about concealing assets addresses how savings are perceived by others, not why total savings failed to grow. The explanation involving transfer fees introduces an external cost not implied by the passage and does not directly resolve the deposit-versus-accumulation discrepancy. The remittance explanation would affect income rather than explain why increased deposits did not raise total savings; moreover, it would tend to increase savings, not leave them unchanged.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MOVF69', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing an article about the kenaf plant for a school agricultural journal and wants to emphasize its environmental advantages over traditional paper sources. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2O1Q8U0', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In a 2022 survey of freshwater biodiversity in the Dinaric Alps, herpetologist Jovan Petrić documented an unexpected _______ over sixty-three percent of the olm salamanders in sampled caves exhibited signs of a chytrid fungal infection that had never before been recorded in the species.', $lyceon_json$[{"key":"A","text":"finding, over"},{"key":"B","text":"finding: over"},{"key":"C","text":"finding over"},{"key":"D","text":"finding; and over"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence structure calls for a colon after "finding" because the preceding clause—"herpetologist Jovan Petrić documented an unexpected finding"—is a complete independent clause, and the material that follows specifies what the finding was. A colon correctly signals that an explanation or elaboration of the finding follows. The comma option creates a comma splice, improperly joining two independent clauses with only a comma. The option with no punctuation produces a run-on sentence, fusing two independent clauses without any separation. The semicolon-plus-conjunction option uses the non-standard combination "; and," which is reserved for separating items in complex lists with internal commas and is not appropriate for joining two independent clauses in this context.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2O9ZEU4', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'A sociologist studying neighborhood change hypothesizes that the displacement of long-term residents from gentrifying areas is driven less by rising rents than by the erosion of local social institutions—such as churches, barbershops, and community organizations—that anchor residents'' sense of belonging. Which finding, if true, would most directly support this hypothesis?', E'Gentrification research has traditionally focused on economic mechanisms: rising property values, increased rents, and the pricing out of lower-income households. More recent scholarship, however, has drawn attention to cultural and social dimensions of displacement. Sociologist Japonica Brown-Saracino has documented cases in which long-term residents leave neighborhoods even when their housing costs remain stable, suggesting that economic explanations alone are insufficient. Other researchers have examined how the closure of locally owned businesses and the transformation of public spaces alter the daily social fabric of a community, potentially making residents feel like strangers in their own neighborhoods.', $lyceon_json$[{"key":"A","text":"In neighborhoods where rents rose sharply but local institutions remained intact, long-term residents moved out at significantly lower rates than in areas where rents were stable but multiple community institutions closed."},{"key":"B","text":"Long-term residents of gentrifying neighborhoods who were surveyed reported that rising rents were a greater source of stress than changes to the social character of their community."},{"key":"C","text":"Neighborhoods that experienced gentrification saw an average rent increase of 37 percent over a five-year period, compared to 11 percent in non-gentrifying areas."},{"key":"D","text":"Community organizations in gentrifying areas that received external funding were able to sustain operations longer than those that relied solely on local membership dues."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis claims that institutional erosion, not rising rents, is the primary driver of displacement. The finding that displacement rates were lower where rents rose but institutions survived than where rents were stable but institutions closed directly supports this by showing institutional loss predicts displacement independently of rent increases. The survey result indicating residents found rent more stressful than social changes would actually undermine the hypothesis by suggesting economic factors weigh more heavily. The statistic about average rent increases in gentrifying versus non-gentrifying areas addresses economic dimensions of gentrification without bearing on whether institutional erosion drives displacement. The finding about external funding sustaining community organizations describes how institutions survive financially, which is tangentially related but does not demonstrate that institutional closure causes residents to leave.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QH5V6M', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'_______ the seventeenth-century shipwreck contained remarkably well-preserved navigational instruments, including a brass astrolabe and two ivory compasses.', $lyceon_json$[{"key":"A","text":"Surveying the seafloor off the coast of Mozambique, marine archaeologist Dr. Yuki Tanabe's preliminary report confirmed that"},{"key":"B","text":"Surveying the seafloor off the coast of Mozambique, marine archaeologist Dr. Yuki Tanabe confirmed that"},{"key":"C","text":"Having been surveyed off the coast of Mozambique, marine archaeologist Dr. Yuki Tanabe confirmed that the seafloor near"},{"key":"D","text":"Having surveyed the seafloor off the coast of Mozambique, it was confirmed by marine archaeologist Dr. Yuki Tanabe that"}]$lyceon_json$::jsonb, 'B', NULL, E'The participial phrase "Surveying the seafloor off the coast of Mozambique" must modify the subject of the main clause that follows. In the correct option, the subject is "marine archaeologist Dr. Yuki Tanabe"—a person who can logically perform the action of surveying. The option whose main-clause subject is "preliminary report" creates a dangling modifier: a report cannot survey the seafloor. The option beginning with "Having been surveyed" produces a dangling modifier in which "marine archaeologist Dr. Yuki Tanabe" appears to have been surveyed, rather than having conducted a survey—the passive voice misattributes the action. The option beginning with "Having surveyed" pairs the participial phrase with the pronoun "it," an expletive that cannot perform the action of surveying; this construction creates both a dangling modifier and an unnecessarily convoluted passive sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RGGC60', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In her study of electoral participation across nineteen municipalities in the Azores, political scientist Catarina Furtado found that voter turnout among residents aged eighteen to _______ increased by nearly fourteen percentage points between 2017 and 2023.', $lyceon_json$[{"key":"A","text":"twenty-nine—historically the cohort least likely to vote in local elections—"},{"key":"B","text":"twenty-nine, historically the cohort least likely to vote in local elections—"},{"key":"C","text":"twenty-nine; historically the cohort least likely to vote in local elections,"},{"key":"D","text":"twenty-nine historically the cohort least likely to vote in local elections,"}]$lyceon_json$::jsonb, 'A', NULL, E'The phrase "historically the cohort least likely to vote in local elections" is a nonessential parenthetical appositive describing "residents aged eighteen to twenty-nine." It interrupts the main clause and must be set off by matching punctuation on both sides. The em-dash pair correctly encloses the parenthetical. The option beginning with a comma and ending with an em dash uses mismatched delimiters—a parenthetical interruption must open and close with the same type of punctuation mark. The option using a semicolon to open the parenthetical is incorrect because a semicolon would signal the start of a new independent clause, but "historically the cohort least likely to vote in local elections" is not an independent clause. The option with no opening punctuation and only a trailing comma fails to signal where the parenthetical begins, causing the reader to misparse the sentence structure.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RJB4PD', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Economist Renata Voronova argues that universal basic income programs reduce labor force participation by diminishing the financial pressure to seek employment. Her analysis of a 2019 pilot in Dauphin, Manitoba, found that recipients worked 13 percent fewer hours than a control group. __________ sociologist Mikhail Abara contends that the Dauphin data actually supports universal basic income: the reduction in hours was concentrated among new parents and students completing degrees, groups whose temporary withdrawal from the workforce yields long-term economic benefits.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"Specifically,"},{"key":"C","text":"However,"},{"key":"D","text":"Accordingly,"}]$lyceon_json$::jsonb, 'C', NULL, E'Voronova claims that universal basic income reduces labor participation, citing a 13 percent drop in hours worked. Abara then reinterprets that same data, arguing the reduction actually supports universal basic income because it came from groups whose withdrawal has long-term benefits. The second claim directly challenges the first''s conclusion. "However," correctly signals this contrast between opposing interpretations of the same evidence. "Moreover," wrongly implies Abara is adding support to Voronova''s argument rather than countering it. "Specifically," incorrectly suggests Abara is elaborating on Voronova''s point when he is reframing it. "Accordingly," incorrectly treats Abara''s counterargument as a logical consequence of Voronova''s position.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RJVSRE', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best describes the relationship between the arguments presented in Text 1 and Text 2?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SGVF7R', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Paleoclimatologist Jun Harada has used oxygen isotope ratios in Greenland ice cores to reconstruct Arctic temperatures over the past 8,200 years, confirming a gradual cooling trend of approximately 0.4 degrees Celsius per millennium throughout most of that period. __________ Harada emphasizes that the cooling pattern reversed sharply around 1850, with Arctic temperatures rising at a rate roughly 47 times faster than the preceding millennial decline, a disparity he attributes to anthropogenic greenhouse gas emissions.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"That said,"},{"key":"C","text":"For example,"},{"key":"D","text":"In other words,"}]$lyceon_json$::jsonb, 'B', NULL, E'The first sentence establishes Harada''s finding of a gradual cooling trend over thousands of years. The sentence after the blank introduces a critical qualification: the cooling reversed sharply around 1850, with warming occurring far faster. This is a concessive pivot — the researcher acknowledges a long-term pattern but flags an important exception to it. "That said," correctly captures this concessive relationship, signaling that what follows qualifies or complicates the preceding claim. "In addition," fails because the reversal is not simply another finding alongside the cooling trend; it fundamentally alters the significance of that trend. "For example," wrongly treats the post-1850 reversal as an illustration of the cooling pattern when it is the opposite. "In other words," incorrectly implies the second sentence restates the first, when it introduces a contradicting development.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SVH7ZV', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes a difference in how the authors of the two texts approach the topic of coral reef restoration?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2V5X4TO', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'A marine biologist claims that the bioluminescent patterns produced by comb jellies serve primarily as a startle response to deter predators. Which finding, if true, would most directly support this claim?', E'Comb jellies, or ctenophores, are translucent marine organisms that produce shimmering bands of light along rows of cilia. Unlike many bioluminescent sea creatures that emit a steady glow, comb jellies generate rapid, pulsating flashes when physically disturbed. Researchers studying the Caribbean species Mnemiopsis leidyi have noted that the intensity and frequency of these light pulses vary depending on the type and severity of mechanical stimulation the organism receives.', $lyceon_json$[{"key":"A","text":"Comb jellies that were exposed to simulated predator contact produced significantly brighter and more rapid flashes than those subjected to non-threatening water currents."},{"key":"B","text":"The cilia responsible for locomotion in comb jellies are structurally similar to those found in other non-bioluminescent marine invertebrates."},{"key":"C","text":"Comb jellies in laboratory settings produce bioluminescent flashes at consistent intervals regardless of whether predators are present."},{"key":"D","text":"Several species of deep-sea fish that prey on comb jellies are themselves capable of producing bioluminescence."}]$lyceon_json$::jsonb, 'A', NULL, E'The claim is that bioluminescent flashes serve as a predator-deterring startle response. The finding that simulated predator contact produces significantly brighter and more rapid flashes than non-threatening currents directly supports this by showing the response is specifically triggered by predator-like stimuli. The observation about cilia structure in non-bioluminescent invertebrates addresses locomotion anatomy, not the function of light production. The finding that flashes occur at consistent intervals regardless of predator presence would actually undermine the claim by suggesting the flashes are not predator-specific. The fact that predatory fish are themselves bioluminescent concerns the predators'' biology, not whether the comb jelly''s flashes function as deterrents.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VB578H', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a research summary for a linguistics conference poster and wants to present the key finding of Dr. Okoro''s study while acknowledging the limitation that qualifies it. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VL3XLN', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'While researching the migration patterns of loggerhead sea turtles across the western _______ that a significant proportion of juveniles were bypassing traditional nesting beaches in favor of previously unused stretches of coastline along the Sardinian peninsula.', $lyceon_json$[{"key":"A","text":"Mediterranean, marine biologist Dr. Anselmo Ferreira observed"},{"key":"B","text":"Mediterranean; marine biologist Dr. Anselmo Ferreira observed"},{"key":"C","text":"Mediterranean marine biologist Dr. Anselmo Ferreira observed"},{"key":"D","text":"Mediterranean: marine biologist Dr. Anselmo Ferreira observed"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence begins with the dependent clause "While researching the migration patterns of loggerhead sea turtles across the western Mediterranean," which must be followed by a comma before the main clause. The comma after "Mediterranean" correctly separates the introductory dependent clause from the independent clause that follows. The semicolon option is incorrect because a semicolon requires an independent clause on both sides, and the "While" clause is dependent. The option without any punctuation creates a garden-path misreading in which "Mediterranean" appears to modify "marine biologist." The colon option is incorrect because a colon requires a complete independent clause before it, and the "While" clause is not independent.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WO55HS', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Tromsø have discovered that Arctic char, a cold-water fish found in northern lakes, can adjust the density of pigment cells in their skin in response to seasonal changes in light. During the prolonged darkness of the polar winter, char develop noticeably paler coloring, which returns to a darker hue as daylight hours increase in spring. The researchers propose that this pigment modulation helps char regulate ultraviolet light absorption, protecting their skin during the intense but brief Arctic summer while conserving metabolic energy during the dark months.', $lyceon_json$[{"key":"A","text":"Arctic char alter their skin pigmentation seasonally, likely as an adaptation to manage UV exposure and energy use."},{"key":"B","text":"The density of pigment cells in Arctic char remains constant, but the visibility of those cells changes with water clarity."},{"key":"C","text":"Researchers have determined that Arctic char migrate to deeper waters during winter to avoid UV radiation damage."},{"key":"D","text":"Arctic char are unique among cold-water fish in possessing pigment cells that respond to temperature fluctuations."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that Arctic char adjust pigment cell density in response to seasonal light changes and that this likely helps regulate UV absorption and conserve energy. The answer that char alter skin pigmentation seasonally as an adaptation for UV management and energy conservation accurately captures this central idea. The claim that pigment cell density remains constant but visibility changes with water clarity contradicts the passage, which says the density itself changes. The suggestion that char migrate to deeper waters is never mentioned and goes beyond the text. The assertion that char are unique among cold-water fish and that pigment responds to temperature is unsupported; the passage discusses light, not temperature, as the trigger.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XIQNKG', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The environmental policy institute published a report examining the effectiveness of carbon pricing mechanisms adopted by seven European nations. The three _______ saw the largest reductions in industrial emissions, with declines averaging twenty-one percent over a six-year period.', $lyceon_json$[{"key":"A","text":"nations that implemented a revenue-neutral carbon tax before 2015"},{"key":"B","text":"nations, that implemented a revenue-neutral carbon tax before 2015,"},{"key":"C","text":"nations, which implemented a revenue-neutral carbon tax before 2015,"},{"key":"D","text":"nations that implemented a revenue-neutral carbon tax before 2015,"}]$lyceon_json$::jsonb, 'A', NULL, E'The relative clause "that implemented a revenue-neutral carbon tax before 2015" is restrictive: it identifies which three of the seven nations the sentence is about. A restrictive clause uses "that" without commas, so the option with "that" and no commas is correct. The option pairing "that" with enclosing commas is incorrect because commas signal a nonrestrictive (extra-information) clause, and Standard English does not use "that" to introduce nonrestrictive clauses. The option using ", which" with commas treats the clause as nonrestrictive, implying that all three nations are already identified and the carbon-tax detail is parenthetical—but the clause is essential for specifying which three nations are meant. The option using "that" with a trailing comma but no opening comma creates an asymmetrical construction that incorrectly separates the relative clause from the verb "saw" with a comma, disrupting the connection between the subject and its predicate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XZWRNG', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In 1973, ethnomusicologist Fumio Koizumi proposed that traditional Japanese music relies on a system of interlocking tetrachords—four-note groupings spanning a perfect fourth—rather than the seven-note scales familiar in Western tonal music. Koizumi identified four distinct tetrachord types, each defined by the intervals between its constituent pitches. What made his framework influential was not merely its descriptive accuracy but its explanatory scope: it accounted for melodies from court gagaku, Buddhist chant, folk song, and theatrical noh alike, genres that earlier scholars had treated as unrelated systems. Subsequent researchers have refined Koizumi''s model, noting that some regional folk traditions employ microtonal inflections that his tetrachord boundaries cannot neatly capture, yet his core insight—that a small set of structural units underlies a vast diversity of genres—remains foundational.', $lyceon_json$[{"key":"A","text":"Koizumi's tetrachord framework provided a unifying structural explanation for diverse Japanese musical genres, and its central premise endures despite later refinements."},{"key":"B","text":"Koizumi demonstrated that Japanese music uses the same fundamental scales as Western tonal music but organizes them into tetrachords rather than full octave patterns."},{"key":"C","text":"Subsequent researchers have largely replaced Koizumi's tetrachord model with systems that better account for microtonal variation in regional folk traditions."},{"key":"D","text":"The primary contribution of Koizumi's work was his discovery that court gagaku and Buddhist chant share identical melodic structures despite their different social functions."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Koizumi''s tetrachord framework as influential because it unified genres previously treated as unrelated, and notes that while refinements have been made, the core insight persists. The answer identifying the framework as a unifying explanation whose central premise endures captures this accurately. The claim that Japanese music uses the same scales as Western music directly contradicts the passage, which contrasts the tetrachord system with Western seven-note scales. The suggestion that researchers have largely replaced the model overstates the passage''s point about refinements; the passage says the core insight remains foundational. The assertion that the primary contribution was discovering identical melodic structures in gagaku and chant is too narrow; the passage emphasizes explanatory scope across many genres, not identity of structure between two specific ones.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
